import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Find all invoices that are overdue as of a given date.
 * Returns invoices sorted by most overdue first.
 * @param {Array} invoices all invoices in the system
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate &&
        inv.dueDate < asOf,
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Summarize VAT by rate across invoices.
 * Returns one entry per VAT rate found, sorted by rate descending.
 * @param {Array} invoices all invoices in the system
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      const lineTotal = line.qty * line.unitPrice;
      const lineDiscount = roundCents(lineTotal * ((line.discountPercent || 0) / 100));
      const lineAmountAfterDiscount = lineTotal - lineDiscount;
      const lineVat = roundCents(lineAmountAfterDiscount * (line.vatRate / 100));

      const rate = line.vatRate;
      if (!vatByRate[rate]) {
        vatByRate[rate] = { base: 0, vat: 0 };
      }
      vatByRate[rate].base += lineAmountAfterDiscount;
      vatByRate[rate].vat += lineVat;
    }
  }

  return Object.entries(vatByRate)
    .map(([rate, { base, vat }]) => ({
      rate: parseInt(rate, 10),
      base: Math.max(0, base),
      vat: Math.max(0, vat),
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * 0.04% per day of amount still due, from dueDate to asOf.
 * Returns 0 if invoice is not overdue.
 * @param {{ dueDate: string, status: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {number} late fee in cents, rounded
 */
export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);

  if (daysOverdue <= 0 || amountDue <= 0) {
    return 0;
  }

  return Math.max(0, roundCents(amountDue * 0.0004 * daysOverdue));
}

