/**
 * Calculate late fee for an invoice.
 * 0.04% per day of amount still due, from dueDate to asOf.
 * Returns 0 if invoice is not overdue.
 * @param {{ dueDate: string, status: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {number} late fee in cents, rounded
 */
export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);

  if (daysOverdue <= 0 || amountDue <= 0) {
    return 0;
  }

  return Math.max(0, roundCents(amountDue * 0.0004 * daysOverdue));
}

/**
 * Get dashboard summary of invoices.
 * @param {Array} invoices all invoices in the system
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  // Count invoices by status
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  for (const inv of invoices) {
    counts[inv.status]++;
  }

  // Calculate outstanding amount (invoices with status 'issued' or 'partially_paid')
  let outstanding = 0;
  const customerDue = {};

  for (const inv of invoices) {
    if (inv.status === 'issued' || inv.status === 'partially_paid') {
      const due = balanceDue(inv);
      outstanding += due;

      // Track customer totals for top customers
      if (!customerDue[inv.customerId]) {
        customerDue[inv.customerId] = 0;
      }
      customerDue[inv.customerId] += due;
    }
  }

  // Get overdue invoices summary
  const overdue = overdueInvoices(invoices, asOf);
  const overdueAmount = overdue.reduce((sum, inv) => sum + inv.due, 0);

  // Get top 3 customers by outstanding amount
  const topCustomers = Object.entries(customerDue)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding: Math.max(0, outstanding),
    overdue: {
      count: overdue.length,
      amount: Math.max(0, overdueAmount),
    },
    topCustomers,
  };
}

