  assert.ok(typeof result.overdue.amount === 'number');
  assert.ok(Array.isArray(result.topCustomers));
});

test('dashboard handles multiple invoices per customer', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
