  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-05',
      lines: [{ sku: 'STICKER', qty: 10 }],
    }).value,
    ['INV-2026-0001'],
  ).value;

  const result = dashboard([inv1, inv2], '2026-10-15');
  const c001 = result.topCustomers.find((c) => c.customerId === 'C-001');
  assert.ok(c001);
  assert.ok(c001.due > 0);
});

test('dashboard clamped amounts to 0', () => {
  const result = dashboard([], '2026-10-15');
  assert.ok(result.outstanding >= 0);
  assert.ok(result.overdue.amount >= 0);
});

