test('dashboard counts invoices by status', () => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  assert.equal(draftInv.ok, true);
  const draft = draftInv.value;

  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
    }).value,
    [],
  );
  assert.equal(issuedInv.ok, true);
  const issued = issuedInv.value;

  const paidInvoiceCreated = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  assert.equal(paidInvoiceCreated.ok, true);

  const paidInvoiceIssued = issueInvoice(paidInvoiceCreated.value, ['INV-2026-0001']);
  assert.equal(paidInvoiceIssued.ok, true);

  const paidResult = recordPayment(paidInvoiceIssued.value, { amount: 303, date: '2026-10-02' });
  assert.equal(paidResult.ok, true);
  const paid = paidResult.value;

  const result = dashboard([draft, issued, paid], '2026-10-15');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.paid, 1);
});

