import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, invoiceTotals } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET30',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoice overdue by one day', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-16');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices excludes invoice due today', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoice due tomorrow', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-14');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  }).value;

  const result = overdueInvoices([draftInv], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued and partially_paid invoices', () => {
  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const tmpInv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-02',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [issuedInv.number],
  ).value;

  const partiallyPaidInv = recordPayment(
    tmpInv2,
    { amount: 100, date: '2026-09-03' },
  ).value;

  const result = overdueInvoices([issuedInv, partiallyPaidInv], '2026-10-15');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, issuedInv.number);
  assert.equal(result[1].number, partiallyPaidInv.number);
});

test('overdueInvoices sorts by daysOverdue most overdue first', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-09-20',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [inv1.number],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [inv1.number, inv2.number],
  ).value;

  const result = overdueInvoices([inv1, inv2, inv3], '2026-10-16');
  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 31);
  assert.equal(result[1].daysOverdue, 12);
  assert.equal(result[2].daysOverdue, 1);
});

test('overdueInvoices calculates correct daysOverdue', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-25');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices includes due amount for issued invoice', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-20');
  assert.equal(result.length, 1);
  assert.ok(result[0].due > 0);
});

test('overdueInvoices calculates correct due amount for partially paid invoice', () => {
  const invoice = recordPayment(
    issueInvoice(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-01',
        lines: [{ sku: 'STICKER', qty: 5 }],
        terms: 'NET14',
      }).value,
      [],
    ).value,
    { amount: 100, date: '2026-10-02' },
  ).value;

  const result = overdueInvoices([invoice], '2026-10-20');
  assert.equal(result.length, 1);
  assert.ok(result[0].due < 288);
  assert.ok(result[0].due > 0);
});

test('overdueInvoices returns invoice with correct structure', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-20');
  assert.equal(result.length, 1);

  const overdue = result[0];
  assert.equal(overdue.number, invoice.number);
  assert.equal(overdue.customerId, 'C-001');
  assert.equal(overdue.dueDate, '2026-10-15');
  assert.ok(typeof overdue.daysOverdue === 'number');
  assert.ok(typeof overdue.due === 'number');
  assert.ok(overdue.daysOverdue > 0);
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-20',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [inv1.number],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-08',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET30',
    }).value,
    [inv1.number, inv2.number],
  ).value;

  const result = overdueInvoices([inv1, inv2, inv3], '2026-10-20');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices does not mutate input array', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const invoices = [invoice];
  const invoicesCopy = JSON.stringify(invoices);

  overdueInvoices(invoices, '2026-10-20');

  assert.equal(JSON.stringify(invoices), invoicesCopy);
});

test('overdueInvoices with EOM terms', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-15',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'EOM',
    }).value,
    [],
  ).value;

  assert.equal(invoice.dueDate, '2026-10-31');

  const result = overdueInvoices([invoice], '2026-11-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with large number of days overdue', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-01-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-15');
  assert.equal(result.length, 1);
  assert.ok(result[0].daysOverdue > 250);
});

test('overdueInvoices returns empty array when asOf is before any due dates', () => {
  const invoice = issueInvoice(
